<script>
export default {
  data: () => ({
    heroVisible: false,
    statsVisible: false,
    featuresVisible: false,
    ctaVisible: false,
    stats: [
      { number: "5+", label: "Years Experience" },
      { number: "20+", label: "Projects Delivered" },
      { number: "3", label: "Core Services" },
      { number: "100%", label: "Client Focused" },
    ],
    features: [
      {
        icon: "mdi-cellphone-link",
        title: "クロスプラットフォーム開発",
        description:
          "iOS / Android / Web を横断し、高品質なアプリケーションを効率的に開発します。",
        tags: ["Swift", "Kotlin", "Flutter", "Vue"],
        gradient: "linear-gradient(135deg, #6366f1, #8b5cf6)",
      },
      {
        icon: "mdi-brain",
        title: "AI・機械学習",
        description:
          "AI・ML技術を活用し、よりスマートで自律的なサービスを実現します。",
        tags: ["LLM", "RAG", "Python", "Codex", "Claude Code"],
        gradient: "linear-gradient(135deg, #06b6d4, #3b82f6)",
      },
      {
        icon: "mdi-chart-bubble",
        title: "チーム開発支援",
        description:
          "アジャイルとスクラムで、チームの力を最大化する仕組みを構築します。",
        tags: ["Agile", "Scrum", "CI/CD"],
        gradient: "linear-gradient(135deg, #10b981, #059669)",
      },
    ],
    observers: [],
  }),
  mounted() {
    setTimeout(() => (this.heroVisible = true), 300);
    this.setupObservers();
  },
  beforeUnmount() {
    this.observers.forEach((obs) => obs.disconnect());
  },
  methods: {
    setupObservers() {
      const options = { threshold: 0.2 };
      const targets = [
        { ref: "statsRef", flag: "statsVisible" },
        { ref: "featuresRef", flag: "featuresVisible" },
        { ref: "ctaRef", flag: "ctaVisible" },
      ];
      targets.forEach(({ ref, flag }) => {
        const el = this.$refs[ref];
        if (!el) return;
        const obs = new IntersectionObserver(([entry]) => {
          if (entry.isIntersecting) {
            this[flag] = true;
            obs.disconnect();
          }
        }, options);
        obs.observe(el);
        this.observers.push(obs);
      });
    },
    scrollToFeatures() {
      const el = this.$refs.featuresRef;
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },
  },
};
</script>

